<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\UserRoleAssignment;

class UserRoleAssignmentCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserRoleAssignment $userRoleAssignment, ?int $size): UserRoleAssignmentCursor
    {
        $next = clone $this;
        $next->sinceUid = $userRoleAssignment->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
